"""Paper plots: python plots.py {training,temporal,profile} [original plotting options].
Each subcommand runs the original plotting program in an isolated module namespace.
"""
import argparse
import sys
from pathlib import Path

SOURCE_TRAINING = 'from __future__ import annotations\n\nimport argparse\nimport json\nfrom pathlib import Path\n\nimport matplotlib.pyplot as plt\nimport numpy as np\n\n\nCASES = [\n    # Row 1: FNO family\n    ("fno_cartesian", "FNO-C"),\n    ("fno_adaptive", "FNO-A"),\n    # Row 2: GNO family\n    ("gno_cartesian", "GNO-C"),\n    ("gno_adaptive", "GNO-A"),\n    # Row 3: GINO family\n    ("gino_cartesian", "GINO-C"),\n    ("gino_adaptive", "GINO-A"),\n]\n\n\ndef moving_average(y: np.ndarray, w: int = 7) -> np.ndarray:\n    y = np.asarray(y, dtype=float)\n    if w <= 1 or y.size <= 2:\n        return y.copy()\n    w = min(int(w), int(y.size))\n    kernel = np.ones(w, dtype=float) / float(w)\n    pad = np.pad(y, (w // 2, w - 1 - w // 2), mode="edge")\n    return np.convolve(pad, kernel, mode="valid")\n\n\ndef load_history(path: Path):\n    hist = json.loads(path.read_text(encoding="utf-8"))\n    ep = np.asarray([r["epoch"] for r in hist], dtype=int)\n    tr = np.asarray([r["train_loss"] for r in hist], dtype=float)\n    va = np.asarray([r["val_loss"] for r in hist], dtype=float)\n    lr = np.asarray([r.get("lr", np.nan) for r in hist], dtype=float)\n    return ep, tr, va, lr\n\n\ndef style_axis(ax):\n    ax.set_xlabel("Epoch")\n    ax.set_ylabel(r"Physics-aware objective $\\mathcal{L}$")\n    ax.grid(True, which="major", alpha=0.18, linewidth=0.6)\n    ax.grid(True, which="minor", alpha=0.08, linewidth=0.4)\n    ax.tick_params(labelsize=8.5)\n\n\ndef plot_single(history: Path, label: str, out: Path, smooth: int, dpi: int):\n    ep, tr, va, lr = load_history(history)\n    best = int(np.nanargmin(va))\n\n    fig, ax = plt.subplots(figsize=(7.4, 4.8))\n    ax.plot(ep, tr, alpha=0.20, lw=0.8, label="Training loss (raw)")\n    ax.plot(ep, va, alpha=0.20, lw=0.8, label="Validation loss (raw)")\n    ax.plot(ep, moving_average(tr, smooth), lw=1.9, label=f"Training ({smooth}-epoch mean)")\n    ax.plot(ep, moving_average(va, smooth), lw=1.9, label=f"Validation ({smooth}-epoch mean)")\n    ax.scatter(\n        ep[best],\n        va[best],\n        s=38,\n        zorder=6,\n        label=f"Best validation: epoch {ep[best]}",\n    )\n    style_axis(ax)\n    ax.set_xlim(max(0, ep.min() - 1), ep.max() + 1)\n    ax.set_title(f"Training convergence — {label}, 200-epoch campaign", fontsize=11.5, weight="semibold")\n    ax.legend(fontsize=8, ncol=2, frameon=True)\n\n    if np.any(np.isfinite(lr)):\n        ax2 = ax.twinx()\n        ax2.plot(ep, lr, ls="--", lw=1.0, alpha=0.50)\n        ax2.set_ylabel("Learning rate", fontsize=9)\n        ax2.ticklabel_format(axis="y", style="sci", scilimits=(0, 0))\n        ax2.tick_params(labelsize=8)\n\n    fig.tight_layout()\n    out.parent.mkdir(parents=True, exist_ok=True)\n    fig.savefig(out, dpi=dpi, bbox_inches="tight", facecolor="white")\n    plt.close(fig)\n    print(f"[SAVE] {out}")\n\n\ndef plot_combined(root: Path, out: Path, smooth: int, dpi: int):\n    fig, axs = plt.subplots(3, 2, figsize=(11.4, 11.2), constrained_layout=True)\n    letters = "abcdef"\n\n    # Keep a common y-range so visual comparison is not distorted by auto-scaling.\n    all_vals = []\n    loaded = {}\n    for case, label in CASES:\n        path = root / f"{case}_seed1234" / "history.json"\n        if not path.is_file():\n            raise FileNotFoundError(path)\n        loaded[case] = load_history(path)\n        _, tr, va, _ = loaded[case]\n        all_vals.extend(tr[np.isfinite(tr) & (tr > 0)])\n        all_vals.extend(va[np.isfinite(va) & (va > 0)])\n    all_vals = np.asarray(all_vals, dtype=float)\n    ymin = max(0.0, float(np.nanpercentile(all_vals, 0.5)))\n    ymax = float(np.nanpercentile(all_vals, 99.5))\n    if not np.isfinite(ymax) or ymax <= ymin:\n        ymax = float(np.nanmax(all_vals))\n    pad = 0.04 * (ymax - ymin) if ymax > ymin else 0.04 * max(abs(ymax), 1.0)\n    ymin = max(0.0, ymin - pad)\n    ymax = ymax + pad\n\n    for i, ((case, label), ax) in enumerate(zip(CASES, axs.flat)):\n        ep, tr, va, lr = loaded[case]\n        best = int(np.nanargmin(va))\n\n        ax.plot(ep, tr, alpha=0.16, lw=0.7, label="Train raw")\n        ax.plot(ep, va, alpha=0.16, lw=0.7, label="Validation raw")\n        ax.plot(ep, moving_average(tr, smooth), lw=1.65, label="Train")\n        ax.plot(ep, moving_average(va, smooth), lw=1.65, label="Validation")\n        ax.scatter(ep[best], va[best], s=24, zorder=5)\n        style_axis(ax)\n        ax.set_ylim(ymin, ymax)\n        ax.set_xlim(max(0, ep.min() - 1), ep.max() + 1)\n        ax.set_title(\n            f"({letters[i]}) {label}   |   best val: {va[best]:.3g} @ epoch {ep[best]}",\n            loc="left",\n            fontsize=10.5,\n            weight="semibold",\n        )\n\n        # Keep the panels clean: LR is summarized only as the faint dotted curve\n        # normalized to the panel height, rather than adding six secondary axes.\n        if np.any(np.isfinite(lr)):\n            lr_ok = lr[np.isfinite(lr)]\n            if lr_ok.size and np.nanmax(lr_ok) > np.nanmin(lr_ok):\n                lrn = (lr - np.nanmin(lr_ok)) / (np.nanmax(lr_ok) - np.nanmin(lr_ok))\n                yrange = ymax - ymin\n                lr_y = ymin + (0.08 + 0.14 * lrn) * yrange\n                ax.plot(ep, lr_y, ls=":", lw=0.9, alpha=0.45, label="LR (normalized)")\n\n        if i == 0:\n            ax.legend(fontsize=7.5, ncol=2, frameon=True, loc="upper right")\n\n    fig.suptitle(\n        "Training convergence for the six controlled 200-epoch neural-operator experiments",\n        fontsize=14,\n        weight="semibold",\n    )\n    out.parent.mkdir(parents=True, exist_ok=True)\n    fig.savefig(out, dpi=dpi, bbox_inches="tight", facecolor="white")\n    plt.close(fig)\n    print(f"[SAVE] {out}")\n\n\ndef main():\n    ap = argparse.ArgumentParser(\n        description="Generate six separate 200-epoch training curves plus one (a)-(f) combined figure."\n    )\n    ap.add_argument(\n        "--root",\n        type=Path,\n        default=Path("output/models/deep200"),\n        help="Directory containing *_seed1234/history.json for the six models.",\n    )\n    ap.add_argument("--out-dir", type=Path, default=Path("output/figures/training"))\n    ap.add_argument("--smooth", type=int, default=7)\n    ap.add_argument("--dpi", type=int, default=450)\n    args = ap.parse_args()\n\n    for case, label in CASES:\n        history = args.root / f"{case}_seed1234" / "history.json"\n        if not history.is_file():\n            raise FileNotFoundError(history)\n        plot_single(\n            history,\n            label,\n            args.out_dir / f"{case}_training_curves_200ep.png",\n            args.smooth,\n            args.dpi,\n        )\n\n    plot_combined(\n        args.root,\n        args.out_dir / "all_six_training_curves_200ep_a-f.png",\n        args.smooth,\n        args.dpi,\n    )\n\n\nif __name__ == "__main__":\n    main()\n'

SOURCE_TEMPORAL = 'from __future__ import annotations\n\n"""\nTemporal error evolution for the paper/reviewer response.\n\nThe script reuses the per-frame PRIMARY metrics already produced by\nevaluation.py. It therefore does NOT rerun neural-network inference.\n\nDefault comparison:\n    FNO-C  -> Cartesian native reference\n    GNO-A  -> adaptive native reference\n    GINO-A -> adaptive native reference\n\nDefault sample:\n    tier     = deep200\n    split    = joint_ood_test\n    scenario = p01_s0048\n    times    = 20, 40, ..., 1000 s\n\nOutputs:\n    temporal_error_evolution.csv\n    temporal_rmse_h.png\n    temporal_rmse_h.pdf\n    temporal_iou.png\n    temporal_iou.pdf\n\nRun from the project root, for example:\n    python plot_temporal_error_evolution.py\n\nor:\n    python plot_temporal_error_evolution.py \\\n        --tier deep200 \\\n        --split joint_ood_test \\\n        --scenario p01_s0048 \\\n        --start 20 --stop 1000 --step 20\n"""\n\nimport argparse\nfrom pathlib import Path\nfrom typing import Dict, List\n\nimport numpy as np\nimport pandas as pd\n\nimport matplotlib\nmatplotlib.use("Agg")\nimport matplotlib.pyplot as plt\n\n\nPROJECT_ROOT = Path(__file__).resolve().parent\n\nCASE_LABELS: Dict[str, str] = {\n    "fno_cartesian": "FNO-C",\n    "gno_adaptive": "GNO-A",\n    "gino_adaptive": "GINO-A",\n}\n\nDEFAULT_CASES = [\n    "fno_cartesian",\n    "gno_adaptive",\n    "gino_adaptive",\n]\n\n\ndef evaluation_csv(\n    tier: str,\n    case: str,\n    seed: int,\n    evaluation_root: Path | None,\n) -> Path:\n    """Return the frame_metrics.csv generated by evaluation.py."""\n    if evaluation_root is None:\n        root = PROJECT_ROOT / "output" / "models" / tier\n    else:\n        root = evaluation_root\n\n    return (\n        root\n        / f"{case}_seed{seed}"\n        / "evaluation"\n        / "frame_metrics.csv"\n    )\n\n\ndef load_case_metrics(\n    csv_path: Path,\n    case: str,\n    split: str,\n    scenario: str,\n) -> pd.DataFrame:\n    if not csv_path.is_file():\n        raise FileNotFoundError(\n            f"Missing evaluation file for {case}:\\n  {csv_path}\\n\\n"\n            "Run evaluation.py for this checkpoint first."\n        )\n\n    df = pd.read_csv(csv_path)\n\n    required = {\n        "split",\n        "scenario_id",\n        "time_s",\n        "time_index",\n        "h_rmse",\n        "wet_iou",\n    }\n    missing = sorted(required.difference(df.columns))\n    if missing:\n        raise RuntimeError(\n            f"{csv_path} is missing required columns: {missing}"\n        )\n\n    sub = df.loc[\n        (df["split"].astype(str) == str(split))\n        & (df["scenario_id"].astype(str) == str(scenario))\n        & (pd.to_numeric(df["time_index"], errors="coerce") > 0)\n    ].copy()\n\n    if sub.empty:\n        available_splits = sorted(df["split"].astype(str).unique().tolist())\n        scenario_candidates = sorted(\n            df.loc[\n                df["split"].astype(str) == str(split),\n                "scenario_id",\n            ].astype(str).unique().tolist()\n        )\n\n        raise RuntimeError(\n            f"No rows found for case={case}, split={split}, "\n            f"scenario={scenario}.\\n"\n            f"Available splits: {available_splits}\\n"\n            f"Scenarios in requested split (first 20): "\n            f"{scenario_candidates[:20]}"\n        )\n\n    sub["time_s"] = pd.to_numeric(sub["time_s"], errors="raise")\n    sub["h_rmse"] = pd.to_numeric(sub["h_rmse"], errors="raise")\n    sub["wet_iou"] = pd.to_numeric(sub["wet_iou"], errors="raise")\n\n    sub = sub.sort_values("time_s").reset_index(drop=True)\n    return sub\n\n\ndef select_requested_times(\n    df: pd.DataFrame,\n    requested_times: np.ndarray,\n    max_time_offset_s: float,\n    case: str,\n) -> pd.DataFrame:\n    """\n    Select the nearest stored frame to each requested physical time.\n\n    The requested time is retained for a common x-axis across model families;\n    actual_time_s is also written to the CSV for reproducibility.\n    """\n    times = df["time_s"].to_numpy(dtype=float)\n    rows: List[dict] = []\n\n    for requested in requested_times:\n        j = int(np.argmin(np.abs(times - requested)))\n        actual = float(times[j])\n        offset = abs(actual - float(requested))\n\n        if offset > max_time_offset_s:\n            raise RuntimeError(\n                f"{case}: nearest stored frame to requested t={requested:g} s "\n                f"is t={actual:g} s (offset={offset:g} s), larger than "\n                f"--max-time-offset {max_time_offset_s:g} s."\n            )\n\n        src = df.iloc[j]\n        rows.append(\n            {\n                "requested_time_s": float(requested),\n                "actual_time_s": actual,\n                "time_offset_s": float(actual - requested),\n                "time_index": int(src["time_index"]),\n                "h_rmse": float(src["h_rmse"]),\n                "wet_iou": float(src["wet_iou"]),\n            }\n        )\n\n    out = pd.DataFrame(rows)\n\n    # Guard against a coarse stored-time grid mapping two requested times\n    # onto the same physical frame.\n    duplicated = out["actual_time_s"].duplicated(keep=False)\n    if duplicated.any():\n        bad = out.loc[\n            duplicated,\n            ["requested_time_s", "actual_time_s"],\n        ].to_dict("records")\n        raise RuntimeError(\n            f"{case}: multiple requested times map to the same stored frame: "\n            f"{bad}. Increase --step or inspect the solver output times."\n        )\n\n    return out\n\n\ndef plot_metric(\n    table: pd.DataFrame,\n    metric: str,\n    ylabel: str,\n    out_base: Path,\n    dpi: int,\n    ylim: tuple[float, float] | None = None,\n) -> None:\n    fig, ax = plt.subplots(figsize=(7.2, 4.5))\n\n    markers = ["o", "s", "^", "D", "v", "P"]\n    for k, (model, grp) in enumerate(table.groupby("model", sort=False)):\n        grp = grp.sort_values("requested_time_s")\n        ax.plot(\n            grp["requested_time_s"],\n            grp[metric],\n            linewidth=1.8,\n            marker=markers[k % len(markers)],\n            markersize=4.0,\n            markevery=max(1, len(grp) // 10),\n            label=model,\n        )\n\n    ax.set_xlabel("Time [s]")\n    ax.set_ylabel(ylabel)\n    ax.set_xlim(\n        float(table["requested_time_s"].min()),\n        float(table["requested_time_s"].max()),\n    )\n\n    if ylim is not None:\n        ax.set_ylim(*ylim)\n\n    ax.grid(True, alpha=0.25)\n    ax.legend(frameon=False, ncol=3)\n    fig.tight_layout()\n\n    fig.savefig(out_base.with_suffix(".png"), dpi=dpi, bbox_inches="tight")\n    fig.savefig(out_base.with_suffix(".pdf"), bbox_inches="tight")\n    plt.close(fig)\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser(\n        description=(\n            "Plot temporal evolution of h-RMSE and wet-area IoU from the "\n            "PRIMARY per-frame metrics written by evaluation.py."\n        )\n    )\n    ap.add_argument("--tier", default="deep200")\n    ap.add_argument("--seed", type=int, default=1234)\n    ap.add_argument("--split", default="joint_ood_test")\n    ap.add_argument("--scenario", default="p01_s0048")\n    ap.add_argument(\n        "--cases",\n        nargs="+",\n        default=DEFAULT_CASES,\n        choices=list(CASE_LABELS),\n        help="Models to include in the temporal comparison.",\n    )\n    ap.add_argument("--start", type=float, default=20.0)\n    ap.add_argument("--stop", type=float, default=1000.0)\n    ap.add_argument("--step", type=float, default=20.0)\n    ap.add_argument(\n        "--max-time-offset",\n        type=float,\n        default=1.0,\n        help=(\n            "Maximum allowed difference [s] between requested time and "\n            "nearest stored solver frame."\n        ),\n    )\n    ap.add_argument(\n        "--evaluation-root",\n        type=Path,\n        default=None,\n        help=(\n            "Optional root containing <case>_seed<seed>/evaluation/. "\n            "Default: output/models/<tier>/"\n        ),\n    )\n    ap.add_argument(\n        "--out",\n        type=Path,\n        default=None,\n        help="Output directory.",\n    )\n    ap.add_argument("--dpi", type=int, default=320)\n    args = ap.parse_args()\n\n    if args.step <= 0:\n        ap.error("--step must be > 0")\n    if args.stop < args.start:\n        ap.error("--stop must be >= --start")\n\n    requested_times = np.arange(\n        args.start,\n        args.stop + 0.5 * args.step,\n        args.step,\n        dtype=float,\n    )\n\n    if args.out is None:\n        out_dir = (\n            PROJECT_ROOT\n            / "output"\n            / "comparison"\n            / args.tier\n            / "temporal_error_evolution"\n            / f"{args.split}_{args.scenario}"\n        )\n    else:\n        out_dir = args.out\n\n    out_dir = out_dir.resolve()\n    out_dir.mkdir(parents=True, exist_ok=True)\n\n    print("=" * 88)\n    print("TEMPORAL ERROR EVOLUTION")\n    print("=" * 88)\n    print(f"[TIER]     {args.tier}")\n    print(f"[SPLIT]    {args.split}")\n    print(f"[SCENARIO] {args.scenario}")\n    print(\n        f"[TIMES]    {requested_times[0]:g} ... "\n        f"{requested_times[-1]:g} s, step={args.step:g} s"\n    )\n    print(f"[CASES]    {\', \'.join(args.cases)}")\n    print(f"[OUT]      {out_dir}")\n    print()\n\n    all_rows: List[pd.DataFrame] = []\n\n    for case in args.cases:\n        csv_path = evaluation_csv(\n            args.tier,\n            case,\n            args.seed,\n            args.evaluation_root.resolve()\n            if args.evaluation_root is not None\n            else None,\n        )\n\n        print(f"[LOAD] {CASE_LABELS[case]} <- {csv_path}")\n        df = load_case_metrics(\n            csv_path=csv_path,\n            case=case,\n            split=args.split,\n            scenario=args.scenario,\n        )\n\n        selected = select_requested_times(\n            df=df,\n            requested_times=requested_times,\n            max_time_offset_s=args.max_time_offset,\n            case=case,\n        )\n        selected.insert(0, "model", CASE_LABELS[case])\n        selected.insert(1, "case", case)\n        selected.insert(2, "split", args.split)\n        selected.insert(3, "scenario_id", args.scenario)\n        all_rows.append(selected)\n\n        print(\n            f"       n={len(selected)} | "\n            f"h_RMSE mean={selected[\'h_rmse\'].mean():.4f} m | "\n            f"IoU mean={selected[\'wet_iou\'].mean():.4f}"\n        )\n\n    table = pd.concat(all_rows, ignore_index=True)\n\n    # Keep the requested model order.\n    order = [CASE_LABELS[c] for c in args.cases]\n    table["model"] = pd.Categorical(\n        table["model"],\n        categories=order,\n        ordered=True,\n    )\n    table = table.sort_values(\n        ["model", "requested_time_s"]\n    ).reset_index(drop=True)\n\n    csv_out = out_dir / "temporal_error_evolution.csv"\n    table.to_csv(csv_out, index=False)\n\n    plot_metric(\n        table,\n        metric="h_rmse",\n        ylabel=r"Flow-depth RMSE, $\\mathrm{RMSE}_h$ [m]",\n        out_base=out_dir / "temporal_rmse_h",\n        dpi=args.dpi,\n    )\n\n    plot_metric(\n        table,\n        metric="wet_iou",\n        ylabel="Wet-area IoU [-]",\n        out_base=out_dir / "temporal_iou",\n        dpi=args.dpi,\n        ylim=(0.0, 1.0),\n    )\n\n    print()\n    print("[SAVE]", csv_out)\n    print("[SAVE]", out_dir / "temporal_rmse_h.png")\n    print("[SAVE]", out_dir / "temporal_rmse_h.pdf")\n    print("[SAVE]", out_dir / "temporal_iou.png")\n    print("[SAVE]", out_dir / "temporal_iou.pdf")\n\n\nif __name__ == "__main__":\n    main()\n'

SOURCE_PROFILE = 'from __future__ import annotations\n\nimport argparse\nfrom pathlib import Path\n\nimport h5py\nimport matplotlib.pyplot as plt\nimport numpy as np\nimport rasterio\nfrom matplotlib.collections import PolyCollection\nfrom matplotlib.colors import LightSource\nfrom rasterio.windows import from_bounds\n\nH_WET = 1.0e-3\n\n\ndef total_depth(U: np.ndarray) -> np.ndarray:\n    """Total mobile flow depth for the project state ordering.\n\n    U = [HF, HSU, HCU, HSL, HCL, MX, MY]\n    h = HF + HSU + HSL\n    """\n    return np.maximum(\n        np.asarray(U[0]) + np.asarray(U[1]) + np.asarray(U[3]),\n        0.0,\n    )\n\n\ndef robust_rgb(src_path: Path, bbox: list[float]) -> np.ndarray:\n    """Read and percentile-stretch the RGB orthophoto in the requested bbox."""\n    xmin, xmax, ymin, ymax = bbox\n    with rasterio.open(src_path) as src:\n        win = from_bounds(xmin, ymin, xmax, ymax, src.transform)\n        win = win.round_offsets().round_lengths()\n        a = src.read([1, 2, 3], window=win, boundless=True)\n\n    a = np.moveaxis(a, 0, -1).astype(float)\n    for k in range(3):\n        b = a[..., k]\n        ok = np.isfinite(b)\n        if not np.any(ok):\n            a[..., k] = 0.0\n            continue\n        lo, hi = np.percentile(b[ok], [1.0, 99.0])\n        a[..., k] = np.clip((b - lo) / max(hi - lo, 1e-6), 0.0, 1.0)\n    return a\n\n\ndef _orient(a: np.ndarray, x: np.ndarray, y: np.ndarray) -> np.ndarray:\n    """Orient rasters so imshow(origin=\'lower\') follows increasing x/y."""\n    q = np.asarray(a)\n    if len(y) > 1 and y[1] < y[0]:\n        q = q[::-1]\n    if len(x) > 1 and x[1] < x[0]:\n        q = q[:, ::-1]\n    return q\n\n\ndef paper_hillshade(z: np.ndarray, x: np.ndarray, y: np.ndarray) -> np.ndarray:\n    """Same grayscale hillshade used by ``inference.py``.\n\n    The DEM is reflected about its mid-range before LightSource shading.  This\n    preserves the established grayscale appearance while using the relief sign\n    adopted in the final inference figures.  The contrast is then compressed\n    toward mid-gray exactly as in the inference plotting routine.\n    """\n    zz = _orient(np.asarray(z, dtype=float), x, y)\n    finite = np.isfinite(zz)\n    if not np.any(finite):\n        return np.full_like(zz, 0.5, dtype=float)\n\n    zmin = float(np.nanmin(zz[finite]))\n    zmax = float(np.nanmax(zz[finite]))\n    zz_inv = (zmin + zmax) - zz\n\n    if not np.all(finite):\n        fill = float(np.nanmedian(zz_inv[finite]))\n        zz_inv = np.where(finite, zz_inv, fill)\n\n    dx = float(abs(x[1] - x[0])) if len(x) > 1 else 1.0\n    dy = float(abs(y[1] - y[0])) if len(y) > 1 else 1.0\n\n    shade = LightSource(azdeg=315, altdeg=45).hillshade(\n        zz_inv,\n        vert_exag=1.0,\n        dx=dx,\n        dy=dy,\n    )\n\n    # Same softer gray range used in inference.py.\n    return np.clip(0.20 + 0.65 * shade, 0.0, 1.0)\n\n\ndef draw_adaptive(ax, mesh, h, cmap, norm):\n    wet = h >= H_WET\n    verts = np.stack(\n        [\n            np.c_[mesh["x0"], mesh["y0"]],\n            np.c_[mesh["x1"], mesh["y0"]],\n            np.c_[mesh["x1"], mesh["y1"]],\n            np.c_[mesh["x0"], mesh["y1"]],\n        ],\n        axis=1,\n    )\n    pc = PolyCollection(\n        verts[wet],\n        array=h[wet],\n        cmap=cmap,\n        norm=norm,\n        edgecolors="none",\n        alpha=0.94,\n    )\n    ax.add_collection(pc)\n    return pc\n\n\ndef main():\n    ap = argparse.ArgumentParser(\n        description=(\n            "Plot p03_s0043 PyDebrisFlow2D Cartesian/adaptive final states on "\n            "the paper hillshade and orthophoto backgrounds."\n        )\n    )\n    ap.add_argument(\n        "--dataset-root",\n        type=Path,\n        default=Path("output/dataset"),\n    )\n    ap.add_argument("--orthophoto", type=Path, required=True)\n    ap.add_argument(\n        "--out",\n        type=Path,\n        default=Path("output/figures/profile.png"),\n    )\n    ap.add_argument("--dpi", type=int, default=450)\n    args = ap.parse_args()\n\n    run_root = args.dataset_root / "runs" / "p03_s0043"\n    cart_h5 = run_root / "cartesian" / "run_data.h5"\n    adapt_h5 = run_root / "adaptive" / "run_data.h5"\n    mesh_path = args.dataset_root / "profiles" / "profile_03_adaptive_mesh.npz"\n\n    for p in (cart_h5, adapt_h5, mesh_path, args.orthophoto):\n        if not p.is_file():\n            raise FileNotFoundError(p)\n\n    with h5py.File(cart_h5, "r") as f:\n        x = f["x"][:].astype(float)\n        y = f["y"][:].astype(float)\n        z0 = f["zb"][0].astype(float)\n        h_cart = total_depth(f["U"][-1])\n        t_cart = float(f["times"][-1])\n\n    with h5py.File(adapt_h5, "r") as f:\n        h_adapt = total_depth(f["U"][-1])\n        t_adapt = float(f["times"][-1])\n\n    mesh = np.load(mesh_path)\n\n    dx = abs(float(x[1] - x[0]))\n    dy = abs(float(y[1] - y[0]))\n    bbox = [\n        float(x.min() - dx / 2),\n        float(x.max() + dx / 2),\n        float(y.min() - dy / 2),\n        float(y.max() + dy / 2),\n    ]\n\n    ortho = robust_rgb(args.orthophoto, bbox)\n    shade = paper_hillshade(z0, x, y)\n\n    wet_values = np.r_[h_cart[h_cart >= H_WET], h_adapt[h_adapt >= H_WET]]\n    vmax = float(np.nanpercentile(wet_values, 99.5)) if wet_values.size else 1.0\n    vmax = max(vmax, 1.0)\n\n    cmap = plt.get_cmap("turbo").copy()\n    cmap.set_bad((0, 0, 0, 0))\n    norm = plt.Normalize(0.0, vmax)\n\n    fig, axs = plt.subplots(\n        2,\n        2,\n        figsize=(12.8, 8.6),\n        sharex=True,\n        sharey=True,\n        constrained_layout=True,\n    )\n\n    titles = [\n        "(a) Terrain-adapted — hillshade",\n        "(b) Terrain-adapted — orthophoto",\n        "(c) Cartesian — hillshade",\n        "(d) Cartesian — orthophoto",\n    ]\n\n    for ax, title in zip(axs.flat, titles):\n        ax.set_title(title, fontsize=11, loc="left", weight="semibold")\n        ax.set_aspect("equal")\n        ax.ticklabel_format(style="plain", useOffset=False)\n        ax.tick_params(labelsize=8)\n\n    # Same final-paper hillshade as inference.py.\n    for ax in (axs[0, 0], axs[1, 0]):\n        ax.imshow(\n            shade,\n            origin="lower",\n            extent=bbox,\n            cmap="gray",\n            vmin=0.0,\n            vmax=1.0,\n            interpolation="nearest",\n            alpha=0.90,\n        )\n\n    # Orthophoto panels.\n    axs[0, 1].imshow(ortho, origin="upper", extent=bbox)\n    axs[1, 1].imshow(ortho, origin="upper", extent=bbox)\n\n    im = draw_adaptive(axs[0, 0], mesh, h_adapt, cmap, norm)\n    draw_adaptive(axs[0, 1], mesh, h_adapt, cmap, norm)\n\n    h_cart_mask = np.ma.masked_where(h_cart < H_WET, _orient(h_cart, x, y))\n    for ax in (axs[1, 0], axs[1, 1]):\n        im = ax.imshow(\n            h_cart_mask,\n            origin="lower",\n            extent=bbox,\n            cmap=cmap,\n            norm=norm,\n            alpha=0.94,\n            interpolation="nearest",\n        )\n\n    for ax in axs[:, 0]:\n        ax.set_ylabel("Northing [m]")\n    for ax in axs[1, :]:\n        ax.set_xlabel("Easting [m]")\n\n    cb = fig.colorbar(im, ax=axs.ravel().tolist(), shrink=0.88, pad=0.025, fraction=0.035)\n    cb.set_label("Flow depth $h$ [m]")\n    fig.suptitle(f"p03_s0043 — PyDebrisFlow2D final state at $t={t_cart:g}$ s", fontsize=12.5, weight="semibold")\n\n    args.out.parent.mkdir(parents=True, exist_ok=True)\n    fig.savefig(\n        args.out,\n        dpi=args.dpi,\n        facecolor="white",\n        bbox_inches="tight",\n    )\n    plt.close(fig)\n    print(f"[SAVE] {args.out}")\n\n\nif __name__ == "__main__":\n    main()\n'

def main():
    parser = argparse.ArgumentParser(description="Plots for the paper")
    parser.add_argument("plot", choices=["training", "temporal", "profile"])
    args, remaining = parser.parse_known_args()
    sys.argv = ["plots.py " + args.plot, *remaining]
    namespace = {"__name__": "__main__", "__file__": str(Path(__file__).resolve())}
    exec(compile(globals()["SOURCE_" + args.plot.upper()], __file__, "exec"), namespace)

if __name__ == "__main__":
    main()
